class AccessTokenWithUserValidation(AccessToken): def verify(self): AccessToken.verify(self)
# get the user of this token user_id = self[api_settings.USER_ID_CLAIM] user = get_user_model().objects.get(id=user_id)
# calculate the current password hash for validation valid_hash = get_current_password_hash(user) # compare the stored hash with the just calculated one if self[PASSWORD_HASH_CLAIM] != valid_hash: raise TokenError(_("Token is invalid or expired"))

class CustomTokenObtainPairSerializer(TokenObtainPairSerializer):
    @classmethod
    def get_token(cls, user):
        token = super().get_token(user)

        # add a custom claim with the user's current password hash
        token[PASSWORD_HASH_CLAIM] = get_current_password_hash(user)

        return token

