class ShowProtectedFilesView(LoginRequiredMixin, View): """ This View is basically an internal redirect to deliver files. Since the media directory is 'internal' in the nginx settings, neither the media directory or any of it's content is not accessible via a URL, but only from within Django. Therefore it passes some permission checks first. """ def get(self, request, content_disposition_type="inline", *args, **kwargs): if USE_X_ACCEL_REDIRECT: response = HttpResponse('') if X_ACCEL_REDIRECT_PREFIX is not None: first_path_element = re.compile("^/([^/]*)/").search(request.path).group(1) request.path = request.path.replace(first_path_element, X_ACCEL_REDIRECT_PREFIX, 1) response['X-Accel-Redirect'] = request.path response['Content-Type'] = ''
else: response = serve(request, request.path, settings.FILES_DIR)
return response

class CreateFilterView(LoginRequiredMixin, View):
    def get_success_url(self):
        next_url = self.request.POST.get('next')
        if next_url:
            return next_url
        return reverse('issue:issue_list_all_view')

    def post(self, request, *args, **kwargs):
        user = self.request.user
        filter_string = self.request.POST.get('string')
        delete = self.request.POST.get('delete', 'false')
        if delete == 'true':
            # even if the queryset is empty there are no problems
            Filter.objects.filter(user=user, queryset=filter_string).delete()
            return HttpResponseRedirect(self.get_success_url())

        if filter_string:
            name = self.request.POST.get('name')
            if not re.match(r"^[\w\s,.]+$", name) or len(name) > 99:
                messages.add_message(request,
                                     messages.WARNING,
                                     _("""Filter name can only contain letters, numbers, commas or periods.
                                       Maximum length is 99 characters""")
                                     )
                return HttpResponseRedirect(self.get_success_url()[:-10])

            typ = self.request.POST.get('typ')
            check = Filter.objects.filter(user=user, typ=typ, queryset=filter_string)
            if check.exists():
                messages.add_message(request,
                                     messages.WARNING,
                                     _("You already have a saved filter for that querystring") +
                                     ": " + check.first().name)
                return HttpResponseRedirect(self.get_success_url())
            if Filter.objects.filter(user=user, name=name, typ=typ).exists():
                messages.add_message(request, messages.WARNING,
                                     _("You already have a saved filter with the name") + ": " + name)
                return HttpResponseRedirect(self.get_success_url())

            Filter(user=user, queryset=filter_string, typ=typ, name=name).save()
        return HttpResponseRedirect(self.get_success_url())

