class IssueExtension(Extension): """ Resolve and link <project.name_short>-<number> to the right issue. """ class IssuePattern(Pattern): def __init__(self, pattern, project, md=None): self.project = project Pattern.__init__(self, pattern, md=md)
def handleMatch(self, m): issue_short_name = m.group(2)
number = int(issue_short_name.split('-')[1]) if number > 0 and \ self.project.nextTicketId <= number: return issue_short_name else: issue_object = Issue.objects.get(project=self.project, number=number) el = markdown.util.etree.Element("a") el.set('href', reverse('issue:detail', kwargs={'project': self.project.name_short, 'sqn_i': number})) el.set("title", markdown.util.AtomicString(issue_object.title)) el.text = markdown.util.AtomicString(issue_short_name)
return el
def __init__(self, project, **kwargs): self.project = project Extension.__init__(self, **kwargs)
def extendMarkdown(self, md): issue_re_pattern = self.create_issue_pattern(self.project)
md.inlinePatterns.register(IssueExtension.IssuePattern(issue_re_pattern, self.project, md), "issuepattern", 100)
@staticmethod def create_issue_pattern(project): return r"(\b%s-[0-9]+)" % project.name_short

class UserExtension(Extension):
    """
    Resolve and link @<username> to the right user.
    """
    class UserPattern(Pattern):
        def handleMatch(self, m):
            user_name_with_at = m.group(2)

            el = markdown.util.etree.Element("a")
            el.set('href', reverse('user_profile:user_profile_page',
                                   kwargs={'username': user_name_with_at[1:]}))  # remove the @ character
            el.text = markdown.util.AtomicString(user_name_with_at)

            return el

    def __init__(self, project, **kwargs):
        self.project = project
        Extension.__init__(self, **kwargs)

    def extendMarkdown(self, md):
        user_re_pattern = self.create_user_pattern(self.project)
        md.inlinePatterns.register(UserExtension.UserPattern(user_re_pattern, md),
                                   "userpattern",
                                   100)

    @staticmethod
    def create_user_pattern(project):
        return r"(@%s\b)" % r"\b|@".join([
            user.username for user in project.get_members()
        ])

