class RepositoryTestConnectionView(LoginRequiredMixin, UserPassesTestMixin, View):
    """Lets a user verify a repository URL is reachable before adding it."""

    def post(self, request, *args, **kwargs):
        url = request.POST.get('url', '')
        try:
            output = Frontend.test_connection(url)
            return JsonResponse({'ok': True, 'output': output})
        except Exception as e:
            return JsonResponse({'ok': False, 'error': str(e)})

    def test_func(self):
        return get_r_object_or_404(self.request.user, Project,
                                   name_short=self.kwargs.get('project'),
                                   ).developer_allowed(self.request.user)

