class SlackIntegrationOAuthView(RedirectView):
    def get_redirect_url(self, *args, **kwargs):
        if not SLACK_ID:
            return reverse("project:edit", kwargs={'project': self.kwargs['project']})
        slack = WebClient("")
        code = self.request.GET['code']
        resp = slack.oauth_access(
            code=code,
            client_id=SLACK_ID,
            client_secret=SLACK_SECRET,
            redirect_uri="https://" + HOST + reverse("integration:slack:auth",
                                                     kwargs={'project': self.kwargs['project']}),
        )
        if resp['ok']:
            si = SlackIntegration()
            si.api_token = resp['access_token']
            si.project = Project.objects.get(name_short=self.kwargs['project'])
            si.save()
            return reverse("integration:slack:update", kwargs={'project': self.kwargs['project'], 'pk': si.pk})
        return reverse("project:edit", kwargs={'project': self.kwargs['project']})

class EmailFormSet(BaseFormSet):
    def clean(self):
        # verify that all entered emails are distinct
        if any(self.errors):
            return
        emails = []
        for form in self.forms:
            email = form.cleaned_data.get('email')
            # NOTE: this None exclusion is important! fill field, add more, add more, invite => failure
            if email in emails and email is not None:
                raise ValidationError(_("You entered the same email twice. Each member can be invited only once."),
                                      code='duplicated_email')
            emails.append(email)
        return emails

    def add_fields(self, form, index):
        form.fields["email"] = EmailField(label=email_field_label)

