class SuccessView(LoginRequiredMixin, View):
    breadcrumb = _l("")

    def get(self, request):
        try:
            invite_list = request.session['invite_list']
            request.session.pop('invite_list', None)
            request.session.modified = True
        except KeyError:
            invite_list = []
        return render(request, 'invite_users/successfully_invited.html', {'invite_list': invite_list})

class IssueConfig(AppConfig):
    name = 'issue'

    def ready(self):
        import issue.signals
        from django.contrib.sites.models import Site

        def db_table_exists(table_name):
            return table_name in connection.introspection.table_names()

        if db_table_exists('django_site'):
            site = Site.objects.get_current()
            site.domain = settings.HOST
            site.name = settings.HOST
            site.save()

class IssuePrioAutocompleteView(AutoCompleteView):
    def get_queryset(self):
        if not self.request.user.is_authenticated:
            return []

        qs = Issue.PRIORITY_TYPES

        if self.q:
            qs = [prio_type for prio_type in qs if self.q.lower() in prio_type[1].lower()]

        return qs

    def get_result_label_html(self, result):
        if result[0] == 4:
            return '<span class="glyphicon glyphicon-arrow-up red"></span>'\
                '<span style="padding-left: .5em">%s</span>' % result[1]
        if result[0] == 3:
            return '<span class="glyphicon glyphicon-arrow-up gly-rotate-45 red"></span>'\
                '<span style="padding-left: .5em">%s</span>' % result[1]
        if result[0] == 2:
            return '<span class="glyphicon glyphicon-arrow-up gly-rotate-90 yellow"></span>'\
                '<span style="padding-left: .5em">%s</span>' % result[1]
        if result[0] == 1:
            return '<span class="glyphicon glyphicon-arrow-up gly-rotate-145 green"></span>'\
                '<span style="padding-left: .5em">%s</span>' % result[1]
        if result[0] == 0:
            return '<span class="glyphicon glyphicon-arrow-up gly-rotate-180 green"></span>'\
                '<span style="padding-left: .5em">%s</span>' % result[1]

    def get_result_label_clean(self, result):
        return str(result[0])

    def get_result_value(self, result):
        return result[0]

