 models.IntegerField(_("Next comment ID"), editable=False, default=1) nextAttachmentId = models.IntegerField(_("Next attachment ID"), editable=False, default=1) nextTimelogId = models.IntegerField(_("Next Timelog ID"), editable=False, default=1) was_in_sprint = models.BooleanField(_("was in a sprint"), editable=False, default=False) archived = models.BooleanField(_("archived"), editable=False, default=False) logged_total = models.DurationField(_("Logged time"), default=datetime.timedelta(seconds=0))
