@receiver(pre_save, sender=Issue)
def handle_follow_unfollow_on_archive_unarchive(sender, instance, *args, **kwargs):
    try:
        old = Issue.objects.get(project=instance.project, number=instance.number)
    except ObjectDoesNotExist:
        return

    # unfollow/follow in archive/unarchive (activity stream)
    if not old.archived and instance.archived:
        for user in followers(instance.project):
            unfollow_issue(user, instance)
    if old.archived and not instance.archived:
        for user in followers(instance.project):
            follow_issue(user, instance)

@receiver(pre_save, sender=Issue)
def set_kanbancol(sender, instance, *args, **kwargs):
    instance.was_in_sprint = False

@receiver(pre_save, sender=Issue)
def set_kanbancol(sender, instance, *args, **kwargs):
    """
    This signal handler has to be the last one. Handlers are called in reverse
    order of connection and this handler is vital.
    """
    if not hasattr(instance, 'kanbancol'):
        instance.kanbancol = instance.project.kanbancol.first()
    # This is necessary for model mommy to work properly
    if instance.kanbancol.project.id != instance.project.id:
        instance.kanbancol = instance.project.kanbancol.first()
    return

def invalidate_cache(sender, instance, **kwargs):
    # remove duplicate signals if m2m changes

    if kwargs.get('action') == 'pre_add' or kwargs.get('action') == 'pre_remove':
        return

    # only delete board_template on column change
    fields = kwargs.get('update_fields')
    delete_backlog = True
    delete_board = True
    if fields and len(fields) == 1 and 'kanbancol' in fields:
        delete_backlog = False

    if isinstance(instance, Punch):
        issue = instance.issue
    else:
        issue = instance

    # invalidate cache templates only for the users involved
    user_list = issue.project.get_members()
    if sender == Issue.participant.through:
        user_list = user_list.filter(id__in=kwargs.get('pk_set'))
    if isinstance(instance, Punch):
        user_list = user_list.filter(id=instance.user.id)

    # invalidate backlog templates, if first noninactive sprint is created or last one gets deleted
    if isinstance(instance, Sprint):
        proj = instance.project
        count = proj.sprint.filter(enddate__isnull=True).count()
        if count > 1 or (count > 0 and not kwargs.get('created')):
            return
        delete_board = False
        issue = instance.project.issue.without_sprint().not_archived()
    else:
        issue = [issue]

    # delete cached templates for all users in project
    for iss in issue:
        for user in user_list:
            if delete_backlog:
                key = make_template_fragment_key('backlog_issue_template',
                                                 [iss.project.name_short, iss.number, user.username])
                cache.delete(key)

            if delete_board:
                key2 = make_template_fragment_key('sprintboard_issue_template',
                                                  [iss.project.name_short, iss.number, user.username])
                cache.delete(key2)

def process_order_by(request, issues):
    # transfer order_by and reverse GET parameter to session object
    if request.GET.get('order_by') is not None:
        request.session['order_by'] = request.GET.get('order_by')
    if request.GET.get('reverse') is not None:
        request.session['reverse'] = request.GET.get('reverse')

    order_type = request.session.get('order_by', 'number')
    reverse = request.session.get('reverse', 'false')
    if order_type in ('number', 'title', 'type', 'kanbancol'):
        if reverse == 'true':
            issues = issues.order_by('-'+order_type, 'number')
        else:
            issues = issues.order_by(order_type, 'number')
    elif order_type in ('priority', 'storypoints'):
        if reverse == 'true':
            issues = issues.order_by(order_type, 'number')
        else:
            issues = issues.order_by('-'+order_type, 'number')
    return issues

