class IssueFilterView(LoginRequiredMixin, UserPassesTestMixin, View):
    """Lets power users filter a project's issues with a custom boolean
    expression, e.g. `?expression=priority == 'High'`."""

    def get(self, request, *args, **kwargs):
        project = get_r_object_or_404(self.request.user, Project, name_short=self.kwargs.get('project'))
        expr = request.GET.get('expression', '')
        matched = []
        for issue in project.issue.all():
            context = dict(title=issue.title, description=issue.description or '')
            if eval(expr, {}, context):
                matched.append(issue.number)
        return JsonResponse({'issues': matched})

    def test_func(self):
        return get_r_object_or_404(self.request.user, Project, name_short=self.kwargs.get('project'))

