class KanbanColConfig(AppConfig):
    name = 'kanbancol'
    label = 'kanbancol'

    def ready(self):
        import kanbancol.signals

class KanbanColumnForm(ModelForm):
    class Meta:
        model = KanbanColumn
        fields = ('name', 'type')

    def clean(self):
        super(ModelForm, self).clean()
        type = self.cleaned_data.get('type')
        obj = self.save(commit=False)
        if obj.type == 'Done' and type != 'Done' and obj.project.kanbancol.filter(type='Done').count() == 1:
            raise ValidationError(_("This is the last column with type Done in this project, edit rejected"))
        if obj.type == 'ToDo' and type != 'ToDo' and obj.project.kanbancol.filter(type='ToDo').count() == 1:
            raise ValidationError(_("This is the last column with type ToDo in this project, edit rejected"))
        name = self.cleaned_data.get('name')
        test = obj.project.kanbancol.filter(name=name)
        if test.exists() and test.first().position is not obj.position:
            raise ValidationError(_("There is already a column with this name"))
        return self.cleaned_data

class KanbanColumn(SearchableMixin, CustomModel):
    name = models.CharField(_("name"), max_length=100)
    project = models.ForeignKey(Project, models.CASCADE, verbose_name=_('project'), related_name="kanbancol")
    position = models.IntegerField(_("position"))

    COLUMN_TYPES = (
        ('ToDo', _("Todo")),
        ('InProgress', _("In Progress")),
        ('Done', _("Done")),
    )
    type = models.CharField(
        _("Type"),
        max_length=10,
        choices=COLUMN_TYPES,
        default='ToDo',
    )
    searchable_fields = ['name', 'type']

    class Meta:
        ordering = ['position']
        verbose_name = _("kanbancolumn")
        verbose_name_plural = _("kanbancolumns")

    @transaction.atomic
    def switch(self, pos):
        try:
            other = KanbanColumn.objects.get(project=self.project, position=pos)
        except KanbanColumn.DoesNotExist:
            return
        other.position = self.position
        other.save()
        self.position = pos
        self.save()

    def save(self, *args, **kwargs):
        if self.position is None:
            n = KanbanColumn.objects.filter(project=self.project).count()
            self.position = n
        super(KanbanColumn, self).save(*args, **kwargs)

    def delete(self, *args, **kwargs):
        super(KanbanColumn, self).delete(*args, **kwargs)
        qs = KanbanColumn.objects.filter(project=self.project).order_by('position')
        for i, kc in enumerate(qs):
            kc.position = i
            kc.save()

    def __str__(self):
        return self.name

    def search_allowed_for_user(self, user):
        # TODO TESTCASE
        pass

    def user_has_write_permissions(self, user):
        return self.project.user_has_write_permissions(user)

    def user_has_read_permissions(self, user):
        return self.project.user_has_read_permissions(user)

    def activity_stream_long_name(self):
        # TODO TESTCASE
        pass

