class HomeView(ShowMoreMixin, TemplateView):
    """
    The landing page.
    It shows a default home page if the user is not logged in.
    If he's logged in, it shows the user dashboard.
    """
    hide_breadcrumbs = True
    items_per_page = 15

    def get(self, request, *args, **kwargs):
        # show dashboard if a user is logged in
        if request.user.is_authenticated:
            self.template_name = "landing_page/dashboard.html"

            # check if the user wants to unfollow a project
            if request.GET.get("unfollow", "") != "":
                unfollow_project(request.user, Project.objects.get(pk=request.GET['unfollow']))

            # get the items of the activity stream
            self.item_list = cache.get('activity_items_'+request.user.username)
            if not self.item_list:
                self.item_list = check_activity_permissions(request.user, user_stream(request.user))
                cache.set('activity_items_'+request.user.username, self.item_list, 60*60*24*31)

        else:
            self.template_name = "landing_page/home.html"

        return TemplateView.get(self, request, *args, **kwargs)

class csrfUpdateMiddleware(MiddlewareMixin):

    needs_update = ['backlog/backlog_list.html', 'sprint/sprintboard.html']

    def process_response(self, request, response):
        if isinstance(response, TemplateResponse) and response.template_name[0] in self.needs_update:
            content = response.content
            token = get_token(request)
            replace = b"name=\'csrfmiddlewaretoken\' value=\'" + token.encode() + b"\'"
            regex = re.compile(br"name=\'csrfmiddlewaretoken\'\s*value=\'\w*\'")
            response.content = re.sub(regex, replace, content)
        return response

unit.function:
def get_r_object_or_404(user, klass, *args, **kwargs):
    result = get_object_or_404(klass, *args, **kwargs)
    if not isinstance(result, CustomModel) or not result.user_has_read_permissions(user):
        raise Http404(_("Either the request object does not exist or you don't have the necessary " +
                        "permissions to access it."))
    return result

def has_r_object_or_zero(user, klass, *args, **kwargs):
    try:
        get_r_object_or_404(user, klass, *args, **kwargs)
    except Http404:
        return 0
    return 1

def get_w_object_or_404(user, klass, *args, **kwargs):
    result = get_object_or_404(klass, *args, **kwargs)
    if not isinstance(result, CustomModel) or not result.user_has_write_permissions(user):
        raise Http404(_("Either the request object does not exist or you don't have the necessary " +
                        "permissions to access it."))
    return result

def has_w_object_or_zero(user, klass, *args, **kwargs):
    try:
        get_w_object_or_404(user, klass, *args, **kwargs)
    except Http404:
        return 0
    return 1

unit.class:
class __ABCModel(models.Model, metaclass=__AbstractModelMeta):
    class Meta:
        abstract = True

class CustomModel(__ABCModel):
    class Meta:
        abstract = True

    @abstractmethod
    def user_has_read_permissions(self, user):
        """
        Call this method to check if a certain user has read permissions on an object of this model.

        It should return True if the user has the permissions, otherwise False.
        """
        raise NotImplementedError("Please Implement this method")

    @abstractmethod
    def user_has_write_permissions(self, user):
        """
        Call this method to check if a certain user has write permissions on an object of this model.

        It should return True if the user has the permissions, otherwise False.
        """
        raise NotImplementedError("Please Implement this method")

    def activity_stream_short_name(self):
        """
        The short name of this model for displaying in the activity stream.
        """
        return self.__str__()

    def activity_stream_long_name(self):
        """
        The long name of this model for displaying in the activity stream.
        """
        return self.__repr__()

