if issue_changed: changed_data = signals.fields_to_changed_data(issue_to_change, [tup[0] for tup in attrs_to_set])
# handle timelogging separately for tdiff in timelogs: timelog = Timelog(user=glob_user, issue=issue_to_change, time=tdiff) timelog.save()
for attr in attrs_to_set: # process all parsed attributes to change field = issue_to_change.__getattribute__(attr[0])
if str(type(field)).startswith("<class 'django.db.models"): # cleanup assignee before setting first new assignee if attr[0] == "assignee" and cleanup_asignee: cleanup_asignee = False field.clear()
# we have a related field -> call add field.add(attr[1]) else: # no db model field, simply assign value issue_to_change.__setattr__(attr[0], attr[1]) issue_to_change.save()
if issue_created: signals.create.send(sender=Issue, instance=issue_to_change, user=user)
if not issue_created and issue_changed: signals.modify.send(sender=Issue, instance=issue_to_change, user=user, changed_data=changed_data)

